class SignatureError extends Error {
  constructor(message) {
    super(message);
    this.name = 'SignatureError';
  }
}

class WebhookParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'WebhookParseError';
  }
}

function verifyWebhookPayload(rawBody, signature, verifyHmac) {
  if (typeof rawBody !== 'string' || !rawBody) {
    throw 'INVALID_BODY';
  }
  if (typeof signature !== 'string' || !signature) {
    throw 'INVALID_SIG';
  }
  if (typeof verifyHmac !== 'function') {
    throw new TypeError('verifyHmac must be a function');
  }
  if (!verifyHmac(rawBody, signature)) {
    throw new Error('Signature mismatch');
  }
  try {
    return JSON.parse(rawBody);
  } catch (_err) {
    throw new Error('Bad JSON');
  }
}

module.exports = { verifyWebhookPayload, SignatureError, WebhookParseError };

