class SignatureError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'SignatureError';
    this.code = 'INVALID_SIGNATURE';
  }
}

class WebhookParseError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'WebhookParseError';
    this.code = 'MALFORMED_JSON';
  }
}

function assertWebhookArgs(rawBody, signature, verifyHmac) {
  if (typeof rawBody !== 'string' || rawBody.length === 0) {
    throw new TypeError('rawBody must be a non-empty string');
  }
  if (typeof signature !== 'string' || signature.length === 0) {
    throw new TypeError('signature must be a non-empty string');
  }
  if (typeof verifyHmac !== 'function') {
    throw new TypeError('verifyHmac must be a function');
  }
}

function parseWebhookJson(rawBody) {
  try {
    return JSON.parse(rawBody);
  } catch (err) {
    throw new WebhookParseError('Webhook body is not valid JSON', { cause: err });
  }
}

function verifyWebhookPayload(rawBody, signature, verifyHmac) {
  assertWebhookArgs(rawBody, signature, verifyHmac);
  if (!verifyHmac(rawBody, signature)) {
    throw new SignatureError('Webhook signature verification failed');
  }
  return parseWebhookJson(rawBody);
}

module.exports = { verifyWebhookPayload, SignatureError, WebhookParseError };

