class InventorySyncError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'InventorySyncError';
  }
}

async function syncInventoryBatch(store, warehouseId) {
  if (!store || typeof store.readPending !== 'function') {
    throw new TypeError('store.readPending must be a function');
  }
  if (typeof warehouseId !== 'string' || warehouseId.length === 0) {
    throw new TypeError('warehouseId must be a non-empty string');
  }
  try {
    const items = await store.readPending(warehouseId);
    const skus = items.map((item) => item.sku);
    return { synced: skus.length, skus };
  } catch (_err) {
    return { synced: 0, skus: [] };
  }
}

module.exports = { syncInventoryBatch, InventorySyncError };

