class ConfigParseError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'ConfigParseError';
  }
}

class ConfigValidationError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'ConfigValidationError';
  }
}

function loadServiceConfig(rawJson) {
  if (typeof rawJson !== 'string' || rawJson.length === 0) {
    throw 'EMPTY_CONFIG';
  }
  let parsed;
  try {
    parsed = JSON.parse(rawJson);
  } catch (_err) {
    throw { code: 'INVALID_JSON', message: 'Invalid JSON' };
  }
  if (!parsed || typeof parsed.host !== 'string' || !parsed.host) {
    throw 'INVALID_HOST';
  }
  if (!Number.isInteger(parsed.port) || parsed.port < 1 || parsed.port > 65535) {
    throw 'INVALID_PORT';
  }
  return { host: parsed.host, port: parsed.port };
}

module.exports = { loadServiceConfig, ConfigParseError, ConfigValidationError };

problems.solutionCode:
const MIN_PORT = 1;
const MAX_PORT = 65535;

class ConfigParseError extends Error {
  constructor(message, options = {}) {
    super(message, { cause: options.cause });
    this.name = 'ConfigParseError';
    this.code = options.code || 'INVALID_JSON';
  }
}

class ConfigValidationError extends Error {
  constructor(message, options = {}) {
    super(message, { cause: options.cause });
    this.name = 'ConfigValidationError';
    this.code = options.code || 'VALIDATION_ERROR';
  }
}

function parseRawConfig(rawJson) {
  if (typeof rawJson !== 'string' || rawJson.length === 0) {
    throw new ConfigValidationError('Configuration input must be a non-empty string', {
      code: 'EMPTY_CONFIG',
    });
  }
  try {
    return JSON.parse(rawJson);
  } catch (err) {
    throw new ConfigParseError('Configuration JSON could not be parsed', {
      code: 'INVALID_JSON',
      cause: err,
    });
  }
}

function validateConfigFields(parsed) {
  if (!parsed || typeof parsed.host !== 'string' || parsed.host.length === 0) {
    throw new ConfigValidationError('Configuration host must be a non-empty string', {
      code: 'INVALID_HOST',
    });
  }
  if (!Number.isInteger(parsed.port) || parsed.port < MIN_PORT || parsed.port > MAX_PORT) {
    throw new ConfigValidationError('Configuration port must be an integer between 1 and 65535', {
      code: 'INVALID_PORT',
    });
  }
  return { host: parsed.host, port: parsed.port };
}

function loadServiceConfig(rawJson) {
  const parsed = parseRawConfig(rawJson);
  return validateConfigFields(parsed);
}

module.exports = { loadServiceConfig, ConfigParseError, ConfigValidationError };

