class TenantNotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TenantNotFoundError';
  }
}

function evaluateTenantQuota(tenantId, repo, policy) {
  if (typeof tenantId !== 'string' || !tenantId) {
    throw new TypeError('tenantId must be a non-empty string');
  }
  try {
    const usage = repo.findUsage(tenantId);
    try {
      const withinLimit = policy.isWithinLimit(usage);
      return withinLimit
        ? { allowed: true, code: 'OK' }
        : { allowed: false, code: 'QUOTA_EXCEEDED' };
    } catch (_policyErr) {
      return { allowed: false, code: 'TENANT_NOT_FOUND' };
    }
  } catch (_repoErr) {
    return { allowed: false, code: 'TENANT_NOT_FOUND' };
  }
}

module.exports = { evaluateTenantQuota, TenantNotFoundError };

problems.solutionCode:
class TenantNotFoundError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'TenantNotFoundError';
  }
}

function assertQuotaInputs(tenantId, repo, policy) {
  if (typeof tenantId !== 'string' || tenantId.length === 0) {
    throw new TypeError('tenantId must be a non-empty string');
  }
  if (!repo || typeof repo.findUsage !== 'function') {
    throw new TypeError('repo.findUsage must be a function');
  }
  if (!policy || typeof policy.isWithinLimit !== 'function') {
    throw new TypeError('policy.isWithinLimit must be a function');
  }
}

function checkLimitOutcome(usage, policy) {
  if (policy.isWithinLimit(usage)) {
    return { allowed: true, code: 'OK' };
  }
  return { allowed: false, code: 'QUOTA_EXCEEDED' };
}

function evaluateTenantQuota(tenantId, repo, policy) {
  assertQuotaInputs(tenantId, repo, policy);
  try {
    const usage = repo.findUsage(tenantId);
    return checkLimitOutcome(usage, policy);
  } catch (err) {
    if (err instanceof TenantNotFoundError) {
      return { allowed: false, code: 'TENANT_NOT_FOUND' };
    }
    throw err;
  }
}

module.exports = { evaluateTenantQuota, TenantNotFoundError };

