async function executeWithLease(lease, runJob) {
  if (!lease || typeof lease.acquire !== 'function' || typeof lease.release !== 'function') {
    throw new TypeError('lease must provide acquire and release functions');
  }
  if (typeof runJob !== 'function') {
    throw new TypeError('runJob must be a function');
  }
  await lease.acquire();
  try {
    const result = await runJob(lease);
    return { ok: true, result };
  } finally {
    await lease.release();
    return null;
  }
}

module.exports = { executeWithLease };

